with with_windows as (select *, count(amount) over w_ordered as running_count_amount, avg(amount) over w_ordered as running_avg_amount, min(amount) over w_ordered as running_min_amount, lead(amount, 2) over (partition by method, order_id order by paid_at, id) as next_amount from payments window w_ordered as (partition by order_id order by paid_at, id rows between unbounded preceding and current row)) select id, order_id, method, amount, status, running_avg_amount, running_min_amount, case when method rlike '^(card|promptpay)$' then 'PRIORITY' else 'GROUP_A' end as method_zone from with_windows order by amount nulls first, status desc
